From f6a0b7491f0523ad92bd59150b408a2282e86011 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:30:06 +0100
Subject: [PATCH] applets/weather: show observation time and when notices end

The widget never said how old the current conditions were, and notices
only showed when they start. Show the observation time under the current
conditions, and give notices an end time where DWD and NOAA provide one.

BUG: 523652
---
 applets/weather/ions/dwd/ion_dwd.cpp     |  4 ++++
 applets/weather/ions/noaa/ion_noaa.cpp   |  3 +++
 applets/weather/qml/TopPanel.qml         | 24 ++++++++++++++++++++++++
 applets/weather/qml/WarningsPage.qml     |  9 ++++++++-
 applets/weather/weatherdata/warnings.cpp | 13 +++++++++++++
 applets/weather/weatherdata/warnings.h   |  5 +++++
 6 files changed, 57 insertions(+), 1 deletion(-)

diff --git a/applets/weather/ions/dwd/ion_dwd.cpp b/applets/weather/ions/dwd/ion_dwd.cpp
index 88cf580a8..ef84c468d 100644
--- a/applets/weather/ions/dwd/ion_dwd.cpp
+++ b/applets/weather/ions/dwd/ion_dwd.cpp
@@ -521,6 +521,10 @@ bool DWDIon::parseForecastData(const QByteArray &data)
         if (timestamp.has_value()) {
             warning.setTimestamp(timestamp.value());
         }
+        const auto endTimestamp = parseDateFromMSecs(warningMap[u"end"_s]);
+        if (endTimestamp.has_value()) {
+            warning.setEndTimestamp(endTimestamp.value());
+        }

         warnings->addWarning(warning);
     }
diff --git a/applets/weather/ions/noaa/ion_noaa.cpp b/applets/weather/ions/noaa/ion_noaa.cpp
index 28346f1cc..16d2d2645 100644
--- a/applets/weather/ions/noaa/ion_noaa.cpp
+++ b/applets/weather/ions/noaa/ion_noaa.cpp
@@ -618,6 +618,9 @@ void NOAAIon::updateWeather()
             // TODO: Add a Headline parameter to the plugin and the applet
             Warning warning(alert.priority, u"<p><b>%1</b></p>%2"_s.arg(alert.headline, alert.description));
             warning.setTimestamp(alert.startTime);
+            if (alert.endTime.isValid()) {
+                warning.setEndTimestamp(alert.endTime);
+            }
             warnings->addWarning(warning);
         }

diff --git a/applets/weather/qml/TopPanel.qml b/applets/weather/qml/TopPanel.qml
index 1b6ebee17..d233a8cc6 100644
--- a/applets/weather/qml/TopPanel.qml
+++ b/applets/weather/qml/TopPanel.qml
@@ -146,6 +146,30 @@ ColumnLayout {

                 opacity: 0.75
             }
+
+            PlasmaComponents.Label {
+                id: observationTimeLabel
+
+                visible: !!root.lastObservation?.observationTimestamp
+
+                Layout.fillWidth: true
+                Layout.alignment: Qt.AlignTop
+
+                text: {
+                    if (!visible) {
+                        return "";
+                    }
+                    const timestamp = root.lastObservation.observationTimestamp;
+                    const isToday = timestamp.toDateString() === new Date().toDateString();
+                    const timeString = isToday ? timestamp.toLocaleTimeString(Qt.locale(), Locale.ShortFormat) : timestamp.toLocaleString(Qt.locale(), Locale.ShortFormat);
+                    return i18nc("@info:status %1 is the time, or date and time, at which the current weather conditions were observed", "Observed at %1", timeString);
+                }
+
+                wrapMode: Text.Wrap
+                textFormat: Text.PlainText
+
+                opacity: 0.75
+            }
         }

         DetailsView {
diff --git a/applets/weather/qml/WarningsPage.qml b/applets/weather/qml/WarningsPage.qml
index b86a42e59..f6c5b54ac 100644
--- a/applets/weather/qml/WarningsPage.qml
+++ b/applets/weather/qml/WarningsPage.qml
@@ -33,7 +33,14 @@ Kirigami.ScrollablePage {
                 Layout.maximumWidth: Kirigami.Units.gridUnit * 10
                 Layout.margins: Kirigami.Units.largeSpacing

-                text: model.timestamp.toLocaleString(Qt.locale(), "ddd yyyy-MM-dd hh:mm:ss")
+                text: {
+                    const format = "ddd yyyy-MM-dd hh:mm:ss";
+                    const start = model.timestamp.toLocaleString(Qt.locale(), format);
+                    if (!model.endTimestamp) {
+                        return start;
+                    }
+                    return i18nc("@label time range of a weather notice, %1 is when it starts and %2 when it ends", "%1 – %2", start, model.endTimestamp.toLocaleString(Qt.locale(), format));
+                }
                 textFormat: Text.PlainText
                 horizontalAlignment: Text.AlignRight
                 wrapMode: Text.Wrap
diff --git a/applets/weather/weatherdata/warnings.cpp b/applets/weather/weatherdata/warnings.cpp
index c85e2dde0..ef2cda855 100644
--- a/applets/weather/weatherdata/warnings.cpp
+++ b/applets/weather/weatherdata/warnings.cpp
@@ -41,6 +41,8 @@ QVariant Warnings::data(const QModelIndex &index, int role) const
         return warning.info().has_value() ? *warning.info() : QVariant();
     case Timestamp:
         return warning.timestamp() ? *warning.timestamp() : QVariant();
+    case EndTimestamp:
+        return warning.endTimestamp() ? *warning.endTimestamp() : QVariant();
     }

     return {};
@@ -54,6 +56,7 @@ QHash<int, QByteArray> Warnings::roleNames() const
     roles[Info] = "info";
     roles[Priority] = "priority";
     roles[Timestamp] = "timestamp";
+    roles[EndTimestamp] = "endTimestamp";

     return roles;
 }
@@ -113,6 +116,11 @@ std::optional<QDateTime> Warning::timestamp() const
     return m_timestamp;
 }

+std::optional<QDateTime> Warning::endTimestamp() const
+{
+    return m_endTimestamp;
+}
+
 void Warning::setInfo(const QString &info)
 {
     m_info = info;
@@ -123,4 +131,9 @@ void Warning::setTimestamp(const QDateTime &timestamp)
     m_timestamp = timestamp;
 }

+void Warning::setEndTimestamp(const QDateTime &endTimestamp)
+{
+    m_endTimestamp = endTimestamp;
+}
+
 #include "moc_warnings.cpp"
diff --git a/applets/weather/weatherdata/warnings.h b/applets/weather/weatherdata/warnings.h
index e5111b5c7..10596d92f 100644
--- a/applets/weather/weatherdata/warnings.h
+++ b/applets/weather/weatherdata/warnings.h
@@ -25,6 +25,7 @@ class Warning;
  * "Priority " + number, string, free text string, required
  * "Info " + number, string, free text string, optional
  * "Timestamp " + number, string, free text string, optional
+ * "EndTimestamp " + number, string, free text string, optional
  */
 class PLASMAWEATHERDATA_EXPORT Warnings : public QAbstractListModel
 {
@@ -39,6 +40,7 @@ public:
         Info,
         Priority,
         Timestamp,
+        EndTimestamp,
     };

     Q_ENUM(WarningModel);
@@ -87,15 +89,18 @@ public:
     QString description() const;
     std::optional<QString> info() const;
     std::optional<QDateTime> timestamp() const;
+    std::optional<QDateTime> endTimestamp() const;

     void setInfo(const QString &info);
     void setTimestamp(const QDateTime &timestamp);
+    void setEndTimestamp(const QDateTime &endTimestamp);

 private:
     Warnings::PriorityClass m_priority;
     QString m_description;
     std::optional<QString> m_info;
     std::optional<QDateTime> m_timestamp;
+    std::optional<QDateTime> m_endTimestamp;
 };

 struct WarningsForeign {
